import{_ as a,o as t,c as e,ag as i}from"./chunks/framework.B5ULsuav.js";const p=JSON.parse('{"title":"如何做出选择","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-选择.md","filePath":"20-专题研究/topic-选择.md","lastUpdated":1778155802000}'),r={name:"20-专题研究/topic-选择.md"};function l(h,o,d,u,s,n){return t(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="如何做出选择" tabindex="-1">如何做出选择 <a class="header-anchor" href="#如何做出选择" aria-label="Permalink to &quot;如何做出选择&quot;">​</a></h1><blockquote><p>专题分析：决策智慧 组合模型：圆融中和 + 自然务实 + 对境不住</p></blockquote><hr><h2 id="一、选择恐惧的根源" tabindex="-1">一、选择恐惧的根源 <a class="header-anchor" href="#一、选择恐惧的根源" aria-label="Permalink to &quot;一、选择恐惧的根源&quot;">​</a></h2><p>害怕选错，是因为想要一个&quot;绝对正确的答案&quot;。</p><blockquote><p><strong>&quot;经验也只能参考，不能教条主义。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></p><p>没有绝对正确的选择，只有当下最适合的选择。</p><blockquote><p><strong>&quot;缘起性空——一切不永恒，所以可改变。这是个好消息——正因为会变化，我们才能通过努力让它变好。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></p><hr><h2 id="二、决策关键原则" tabindex="-1">二、决策关键原则 <a class="header-anchor" href="#二、决策关键原则" aria-label="Permalink to &quot;二、决策关键原则&quot;">​</a></h2><h3 id="_1-先静心-再选" tabindex="-1">1. 先静心，再选 <a class="header-anchor" href="#_1-先静心-再选" aria-label="Permalink to &quot;1. 先静心，再选&quot;">​</a></h3><blockquote><p><strong>&quot;以最清净最客观的心去看待一切，包括看待自己。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></p><p>不要让&quot;害怕选错&quot;的恐惧来驱动选择。先深呼吸，心静下来。</p><h3 id="_2-用整体观判断" tabindex="-1">2. 用整体观判断 <a class="header-anchor" href="#_2-用整体观判断" aria-label="Permalink to &quot;2. 用整体观判断&quot;">​</a></h3><blockquote><p><strong>&quot;在任何一个时空点上，还是有是非对错的标准的——这就是整体观。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></p><p>跳出自我的小圈子：这个选择对整体（家庭/团队/社会）的影响是什么？双方的立场各是什么？</p><h3 id="_3-具体问题具体分析" tabindex="-1">3. 具体问题具体分析 <a class="header-anchor" href="#_3-具体问题具体分析" aria-label="Permalink to &quot;3. 具体问题具体分析&quot;">​</a></h3><blockquote><p><strong>&quot;一切贤圣皆以无为法而有差别——不带主观成见，按照客观实际具体问题具体分析。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a></p><p>不要套用过去的经验，也不要照搬别人的做法。根据<strong>当下的具体情况</strong>来分析。</p><h3 id="_4-选了就放下" tabindex="-1">4. 选了就放下 <a class="header-anchor" href="#_4-选了就放下" aria-label="Permalink to &quot;4. 选了就放下&quot;">​</a></h3><blockquote><p><strong>&quot;因上精进，果上随缘就是中观。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p><p>选之前认真分析，选之后坦然面对。尽力了，就够了。</p><hr><h2 id="三、要不要帮别人" tabindex="-1">三、要不要帮别人 <a class="header-anchor" href="#三、要不要帮别人" aria-label="Permalink to &quot;三、要不要帮别人&quot;">​</a></h2><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><p>不是所有请求都必须答应。量力而行，真诚评估自己能不能帮、该不该帮。</p><hr><h2 id="四、常见决策误区" tabindex="-1">四、常见决策误区 <a class="header-anchor" href="#四、常见决策误区" aria-label="Permalink to &quot;四、常见决策误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>一定要选&quot;对&quot;的</td><td>没有绝对的对错，只有适合当下的选择</td><td><a href="/liaokongjushi-wisdom/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></td></tr><tr><td>选错了就完了</td><td>&quot;一切不永恒，所以可改变&quot;</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></td></tr><tr><td>别人都选A我也该选A</td><td>经验不能照搬，要具体分析自己的情况</td><td><a href="/liaokongjushi-wisdom/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></td></tr><tr><td>拖着不选最安全</td><td>不选择本身也是一种选择，而且往往是最差的选择</td><td>—</td></tr></tbody></table><hr><h2 id="五、推荐模型" tabindex="-1">五、推荐模型 <a class="header-anchor" href="#五、推荐模型" aria-label="Permalink to &quot;五、推荐模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 整体观判断，不走极端</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 抓核心，做决定，不拖延</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — 不被选择的焦虑带跑</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">对法不执</a> — 做了就放下，不纠结结果</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-义">dict-义</a> — 在具体情境中判断&quot;该不该做&quot;</li><li><a href="/liaokongjushi-wisdom/meta-整体观">meta-整体观</a> — 用整体观来做决策</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（全部原话添加原文段落链接，新增概念链接） 来源：金刚经第5分、第7分、第10分，道德经</p></blockquote>',43)])])}const c=a(r,[["render",l]]);export{p as __pageData,c as default};
